          moistureMax: 65.0,
          bowlWaterMin: 50,
          bowlWaterMax: 200,
          bowlFoodMin: 30,
          bowlFoodMax: 100
        },
        capacities: {
          foodTank: 2500,
          waterTank: 3000,
          bowlFoodMaxLimit: 150,
          bowlWaterMaxLimit: 250
        },
