service cloud.firestore {
  match /databases/{database}/documents {
    // Tasks collection (legacy/backwards compatibility)
    match /tasks/{taskId} {
      allow read, write: if request.auth != null;
    }

    // Aegis Paws Pet Feeder Stations
    match /pet_feeders/{stationId} {
      // Allows read and write for authenticated operators (including anonymous auth)
      allow read, write: if request.auth != null;

      // Sub-collections (logs, telemetry streams)
      match /{allChildren=**} {
        allow read, write: if request.auth != null;
      }
    }
  }
}

