}

async connectStation(stationId = "station_01") {
  this.stationId = stationId;
  if (this.unsubscribeFirestore) {
    this.unsubscribeFirestore();
    this.unsubscribeFirestore = null;
  }

  try {
    const docRef = doc(db, "pet_feeders", this.stationId);
    this.unsubscribeFirestore = onSnapshot(
      docRef,
      async (docSnap) => {
        if (!docSnap.exists()) {
          this.logActivity(`Initializing station [${this.stationId}] on Firestore...`, "info");
          await setDoc(docRef, { ...DEFAULT_STATE, updatedAt: serverTimestamp() });
        } else {
          const data = docSnap.data();
          this.state = {
            ...DEFAULT_STATE,
            ...data,
            config: { ...DEFAULT_STATE.config, ...(data.config || {}) },
            capacities: { ...DEFAULT_STATE.capacities, ...(data.capacities || {}) },
          };
          this.isUsingLocalFallback = false;
          this.checkAutoRefillRules();
          this.notify();
        }
      },
      (error) => {
        console.warn("[FeederService] Firestore listener error/permission denied. Falling back to local reactive storage:", error);
        this.isUsingLocalFallback = true;
        this.logActivity(`Firestore restricted (${error.code || "offline"}). Operating in Sovereign Local Mode.`, "warning");
        this.notify();
      }
    );
  } catch (err) {
    console.warn("[FeederService] Failed to establish Firestore connection:", err);
    this.isUsingLocalFallback = true;
    this.notify();
  }
}

async persistState(partialState, logMsg, logType = "info") {
  this.state = {
    ...this.state,
    ...partialState,
    lastUpdated: new Date().toISOString(),
  };
  if (logMsg) this.logActivity(logMsg, logType);
  this.checkAutoRefillRules();
  this.notify();

  if (!this.isUsingLocalFallback) {
    try {
      const docRef = doc(db, "pet_feeders", this.stationId);
      await updateDoc(docRef, { ...partialState, updatedAt: serverTimestamp() });
    } catch (err) {
      console.warn("[FeederService] Write to Firestore failed, retaining local state:", err);
