// Direct REST API verification against Google Cloud Firestore
const API_KEY = "AIzaSyBxSEU6wc-5LuHAbAlXqF5s8PB2KJnP7pA";
const PROJECT_ID = "manhattan-cafe-9fe21";

async function run() {
  console.log("1. Authenticating via Google Identity Toolkit REST API...");
  const authRes = await fetch(`https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=${API_KEY}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      email: "manager@aegispaws.com",
      password: "password123456",
      returnSecureToken: true
    })
  });

  const authData = await authRes.json();
  if (authData.error) {
    console.error("Auth error:", authData.error);
    return;
  }

  const idToken = authData.idToken;
  const uid = authData.localId;
  console.log("Logged in! UID:", uid);

  console.log("2. Querying Firestore REST API for root documents...");
  const listRes = await fetch(`https://firestore.googleapis.com/v1/projects/${PROJECT_ID}/databases/(default)/documents`, {
    headers: { "Authorization": `Bearer ${idToken}` }
  });
  console.log("Root documents status:", listRes.status, listRes.statusText);
  const listData = await listRes.json();
  console.log("Root documents response:", JSON.stringify(listData, null, 2));

  console.log("3. Querying /tasks collection specifically...");
  const tasksRes = await fetch(`https://firestore.googleapis.com/v1/projects/${PROJECT_ID}/databases/(default)/documents/tasks`, {
    headers: { "Authorization": `Bearer ${idToken}` }
  });
  console.log("Tasks collection status:", tasksRes.status, tasksRes.statusText);
  const tasksData = await tasksRes.json();
  console.log("Tasks collection response:", JSON.stringify(tasksData, null, 2));
}

run().catch(console.error);

